"""Sortie ZF2, batch 2: characters are determined by their values at coprime
integers (dchreqz); uniqueness of the induced character (dchrindeq) and the
identities of changeLevel: self, one, mul, GrpHom, inv, trans."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf2lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

ZM = '( Z/nZ ` M )'; ZN = '( Z/nZ ` N )'
def dchr_hyps(w, n):
    return (w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (n, n)),
            w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (n, n)),
            w.s([], 'eqid', '%s = %s' % (DB(n), DB(n))),
            w.s([], 'eqid', '%s = %s' % (LZ(n), LZ(n))))
def P(x, y, n, a='a'):
    """( ( a gcd n ) = 1 -> ( x ` ( Ln ` a ) ) = ( y ` ( Ln ` a ) ) )"""
    return '( %s -> %s = %s )' % (COP(a, n), EV(x, n, a), EV(y, n, a))
def RALP(x, y, n, a='a'): return 'A. %s e. ZZ %s' % (a, P(x, y, n, a))

# ---- dchrindfval: the operation ( N DChrInd M ) unfolded
H2 = '( N e. NN /\\ M e. NN )'
w = W('dchrindfval', 'Value of the operation DChrInd at two levels: the map sending a character mod N to its induced character mod M.')
n = w.s([], 'simpl', '( %s -> N e. NN )' % H2); m = w.s([], 'simpr', '( %s -> M e. NN )' % H2)
d0 = w.s([], 'df-dchrind', 'DChrInd = ( n e. NN , m e. NN |-> %s )' % INDMPT('n', 'm'))
d1 = w.s([d0], 'a1i', '( %s -> DChrInd = ( n e. NN , m e. NN |-> %s ) )' % (H2, INDMPT('n', 'm')))
A2 = '( %s /\\ ( n = N /\\ m = M ) )' % H2
ln = w.s([], 'simprl', '( %s -> n = N )' % A2); lm = w.s([], 'simprr', '( %s -> m = M )' % A2)
c, new = w.congr(INDMPT('n', 'm'), {'n': 'N', 'm': 'M'}, A2, {'n': ln, 'm': lm})
e0 = w.s([], 'fvex', '%s e. _V' % DB('N')); e1 = w.s([e0], 'mptex', '%s e. _V' % INDMPT('N', 'M'))
e2 = w.s([e1], 'a1i', '( %s -> %s e. _V )' % (H2, INDMPT('N', 'M')))
w.qed([d1, c, n, m, e2], 'ovmpod', '( %s -> %s = %s )' % (H2, INDOP('N', 'M'), INDMPT('N', 'M'))); run(w)

# ---- dchreqz: two characters mod N are equal iff they agree at every integer coprime to N
HE = '( N e. NN /\\ X e. %s /\\ Y e. %s )' % (DB('N'), DB('N'))
w = W('dchreqz', 'Two Dirichlet characters mod N are equal iff they agree at the class of every integer coprime to N (extensionality in the integer idiom; from dchreq and the surjectivity of ZRHom).')
f1 = w.s([], 'fveq1', '( X = Y -> %s = %s )' % (EV('X', 'N', 'a'), EV('Y', 'N', 'a')))
f2 = w.s([f1], 'a1d', '( X = Y -> %s )' % P('X', 'Y', 'N'))
f3 = w.s([f2], 'ralrimivw', '( X = Y -> %s )' % RALP('X', 'Y', 'N'))
f4 = w.s([f3], 'a1i', '( %s -> ( X = Y -> %s ) )' % (HE, RALP('X', 'Y', 'N')))
g, z, d, l = dchr_hyps(w, 'N'); u = w.s([], 'eqid', '%s = %s' % (UZ('N'), UZ('N'))); b = w.s([], 'eqid', '%s = %s' % (BZ('N'), BZ('N')))
n = w.s([], 'simp1', '( %s -> N e. NN )' % HE); x = w.s([], 'simp2', '( %s -> X e. %s )' % (HE, DB('N'))); y = w.s([], 'simp3', '( %s -> Y e. %s )' % (HE, DB('N')))
eq = w.s([g, z, d, u, x, y], 'dchreq', '( %s -> ( X = Y <-> A. k e. %s ( X ` k ) = ( Y ` k ) ) )' % (HE, UZ('N')))
A1 = '( %s /\\ k e. %s )' % (HE, UZ('N'))
CH = '( %s -> ( X ` k ) = ( Y ` k ) )' % RALP('X', 'Y', 'N')
A3 = '( %s /\\ a e. ZZ /\\ k = %s )' % (A1, EV1 := '( %s ` a )' % LZ('N'))
ku = w.s([], 'simp1r', '( %s -> k e. %s )' % (A3, UZ('N'))); ke = w.s([], 'simp3', '( %s -> k = %s )' % (A3, EV1))
lu = w.s([ke, ku], 'eqeltrrd', '( %s -> %s e. %s )' % (A3, EV1, UZ('N')))
n3 = w.s([w.s([], 'simp1l', '( %s -> %s )' % (A3, HE))], 'simp1d', '( %s -> N e. NN )' % A3); n0 = w.s([n3], 'nnnn0d', '( %s -> N e. NN0 )' % A3)
az = w.s([], 'simp2', '( %s -> a e. ZZ )' % A3)
un = w.s([n0, az, w.s([z, u, l], 'znunit', '( ( N e. NN0 /\\ a e. ZZ ) -> ( %s e. %s <-> %s ) )' % (EV1, UZ('N'), COP('a', 'N')))], 'syl2anc', '( %s -> ( %s e. %s <-> %s ) )' % (A3, EV1, UZ('N'), COP('a', 'N')))
cop = w.s([lu, un], 'mpbid', '( %s -> %s )' % (A3, COP('a', 'N')))
r1 = w.s([], 'rsp', '( %s -> ( a e. ZZ -> %s ) )' % (RALP('X', 'Y', 'N'), P('X', 'Y', 'N')))
r2 = w.s([az, r1], 'syl5com', '( %s -> ( %s -> %s ) )' % (A3, RALP('X', 'Y', 'N'), P('X', 'Y', 'N')))
r3 = w.s([cop, r2], 'mpid', '( %s -> ( %s -> %s = %s ) )' % (A3, RALP('X', 'Y', 'N'), EV('X', 'N', 'a'), EV('Y', 'N', 'a')))
k1 = w.s([ke], 'fveq2d', '( %s -> ( X ` k ) = %s )' % (A3, EV('X', 'N', 'a'))); k2 = w.s([ke], 'fveq2d', '( %s -> ( Y ` k ) = %s )' % (A3, EV('Y', 'N', 'a')))
k3 = w.s([k1, k2], 'eqeq12d', '( %s -> ( ( X ` k ) = ( Y ` k ) <-> %s = %s ) )' % (A3, EV('X', 'N', 'a'), EV('Y', 'N', 'a')))
r4 = w.s([r3, k3], 'sylibrd', '( %s -> %s )' % (A3, CH))
r5 = w.s([r4], '3exp', '( %s -> ( a e. ZZ -> ( k = %s -> %s ) ) )' % (A1, EV1, CH))
nf1 = w.s([], 'nfv', 'F/ a %s' % A1)
nf2 = w.s([w.s([], 'nfra1', 'F/ a %s' % RALP('X', 'Y', 'N')), w.s([], 'nfv', 'F/ a ( X ` k ) = ( Y ` k )')], 'nfim', 'F/ a %s' % CH)
r6 = w.s([nf1, nf2, r5], 'rexlimd', '( %s -> ( E. a e. ZZ k = %s -> %s ) )' % (A1, EV1, CH))
n1 = w.s([n], 'adantr', '( %s -> N e. NN )' % A1); n10 = w.s([n1], 'nnnn0d', '( %s -> N e. NN0 )' % A1)
fo = w.s([n10, w.s([z, b, l], 'znzrhfo', '( N e. NN0 -> %s : ZZ -onto-> %s )' % (LZ('N'), BZ('N')))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (A1, LZ('N'), BZ('N')))
kb = w.s([w.s([], 'simpr', '( %s -> k e. %s )' % (A1, UZ('N'))), w.s([b, u], 'unitcl', '( k e. %s -> k e. %s )' % (UZ('N'), BZ('N')))], 'syl', '( %s -> k e. %s )' % (A1, BZ('N')))
ex = w.s([fo, kb, w.inst('foelrn')], 'syl2anc', '( %s -> E. a e. ZZ k = %s )' % (A1, EV1))
r7 = w.s([ex, r6], 'mpd', '( %s -> %s )' % (A1, CH))
r8 = w.s([r7], 'ralrimiva', '( %s -> A. k e. %s %s )' % (HE, UZ('N'), CH))
r9 = w.s([r8, w.s([], 'r19.21v', '( A. k e. %s %s <-> ( %s -> A. k e. %s ( X ` k ) = ( Y ` k ) ) )' % (UZ('N'), CH, RALP('X', 'Y', 'N'), UZ('N')))], 'sylib', '( %s -> ( %s -> A. k e. %s ( X ` k ) = ( Y ` k ) ) )' % (HE, RALP('X', 'Y', 'N'), UZ('N')))
r10 = w.s([r9, eq], 'sylibrd', '( %s -> ( %s -> X = Y ) )' % (HE, RALP('X', 'Y', 'N')))
w.qed([f4, r10], 'impbid', '( %s -> ( X = Y <-> %s ) )' % (HE, RALP('X', 'Y', 'N'))); run(w)

# ---- dchrindeq: uniqueness of the induced character
Y = IND('N', 'M', 'X')
def PZ(z, n, m, a='a'):
    return '( %s -> %s = %s )' % (COP(a, m), EV(z, m, a), EV('X', n, a))
HQ = '( %s /\\ Z e. %s /\\ A. a e. ZZ %s )' % (HX, DB('M'), PZ('Z', 'N', 'M'))
A = '( %s /\\ Z e. %s )' % (HX, DB('M'))
w = W('dchrindeq', 'Uniqueness of the induced character: a character Z mod M agreeing with X at every integer coprime to M is the induced character (Mathlib FactorsThrough.existsUnique, changeLevel_injective).')
hx = w.s([], 'simpl', '( %s -> %s )' % (A, HX)); h3 = w.s([hx], 'simpld', '( %s -> %s )' % (A, H3))
m = w.s([h3], 'simp2d', '( %s -> M e. NN )' % A); zz = w.s([], 'simpr', '( %s -> Z e. %s )' % (A, DB('M')))
yd = w.s([hx, w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (A, Y, DB('M')))
eq = w.s([m, zz, yd, w.inst('dchreqz')], 'syl3anc', '( %s -> ( Z = %s <-> %s ) )' % (A, Y, RALP('Z', Y, 'M')))
A2 = '( %s /\\ a e. ZZ )' % A; A3 = '( %s /\\ %s )' % (A2, COP('a', 'M'))
hx3 = w.s([hx], 'ad2antrr', '( %s -> %s )' % (A3, HX)); a3 = w.s([], 'simplr', '( %s -> a e. ZZ )' % A3); c3 = w.s([], 'simpr', '( %s -> %s )' % (A3, COP('a', 'M')))
v = w.s([hx3, a3, c3, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (A3, EV(Y, 'M', 'a'), EV('X', 'N', 'a')))
b1 = w.s([v], 'eqeq2d', '( %s -> ( %s = %s <-> %s = %s ) )' % (A3, EV('Z', 'M', 'a'), EV(Y, 'M', 'a'), EV('Z', 'M', 'a'), EV('X', 'N', 'a')))
b2 = w.s([b1], 'bicomd', '( %s -> ( %s = %s <-> %s = %s ) )' % (A3, EV('Z', 'M', 'a'), EV('X', 'N', 'a'), EV('Z', 'M', 'a'), EV(Y, 'M', 'a')))
b3 = w.s([b2], 'ex', '( %s -> ( %s -> ( %s = %s <-> %s = %s ) ) )' % (A2, COP('a', 'M'), EV('Z', 'M', 'a'), EV('X', 'N', 'a'), EV('Z', 'M', 'a'), EV(Y, 'M', 'a')))
b4 = w.s([b3], 'pm5.74d', '( %s -> ( %s <-> %s ) )' % (A2, PZ('Z', 'N', 'M'), P('Z', Y, 'M')))
b5 = w.s([b4], 'ralbidva', '( %s -> ( A. a e. ZZ %s <-> %s ) )' % (A, PZ('Z', 'N', 'M'), RALP('Z', Y, 'M')))
b6 = w.s([eq, b5], 'bitr4d', '( %s -> ( Z = %s <-> A. a e. ZZ %s ) )' % (A, Y, PZ('Z', 'N', 'M')))
b7 = w.s([b6], 'biimprd', '( %s -> ( A. a e. ZZ %s -> Z = %s ) )' % (A, PZ('Z', 'N', 'M'), Y))
w.qed([b7], '3impia', '( %s -> Z = %s )' % (HQ, Y)); run(w)

# ---- dchrindid: inducing to the same level is the identity
HI = '( N e. NN /\\ X e. %s )' % DB('N')
w = W('dchrindid', 'Inducing a character to its own level changes nothing (Mathlib changeLevel_self).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HI); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HI, DB('N')))
dv = w.s([w.s([n], 'nnzd', '( %s -> N e. ZZ )' % HI), w.inst('iddvds')], 'syl', '( %s -> N || N )' % HI)
h3 = w.s([n, n, dv], '3jca', '( %s -> ( N e. NN /\\ N e. NN /\\ N || N ) )' % HI)
hx = w.s([h3, x], 'jca', '( %s -> ( ( N e. NN /\\ N e. NN /\\ N || N ) /\\ X e. %s ) )' % (HI, DB('N')))
e1 = w.s([], 'eqidd', '( %s -> %s = %s )' % (COP('a', 'N'), EV('X', 'N', 'a'), EV('X', 'N', 'a')))
e2 = w.s([e1], 'rgenw', 'A. a e. ZZ %s' % PZ('X', 'N', 'N'))
e3 = w.s([e2], 'a1i', '( %s -> A. a e. ZZ %s )' % (HI, PZ('X', 'N', 'N')))
r = w.s([hx, x, e3, w.inst('dchrindeq')], 'syl3anc', '( %s -> X = %s )' % (HI, IND('N', 'N', 'X')))
w.qed([r], 'eqcomd', '( %s -> %s = X )' % (HI, IND('N', 'N', 'X'))); run(w)

# ---- coprmdvdsr: coprimality to M descends to a divisor N of M
HC = '( ( A e. ZZ /\\ N e. ZZ /\\ M e. ZZ ) /\\ N || M /\\ ( A gcd M ) = 1 )'
w = W('coprmdvdsr', 'An integer coprime to M is coprime to every divisor N of M.')
a = w.s([], 'simp11', '( %s -> A e. ZZ )' % HC); n = w.s([], 'simp12', '( %s -> N e. ZZ )' % HC); m = w.s([], 'simp13', '( %s -> M e. ZZ )' % HC)
dv = w.s([], 'simp2', '( %s -> N || M )' % HC); c = w.s([], 'simp3', '( %s -> ( A gcd M ) = 1 )' % HC)
g0 = w.s([a, n, w.inst('gcdcl')], 'syl2anc', '( %s -> ( A gcd N ) e. NN0 )' % HC)
gz = w.s([g0], 'nn0zd', '( %s -> ( A gcd N ) e. ZZ )' % HC)
gd = w.s([a, n, w.inst('gcddvds')], 'syl2anc', '( %s -> ( ( A gcd N ) || A /\\ ( A gcd N ) || N ) )' % HC)
ga = w.s([gd], 'simpld', '( %s -> ( A gcd N ) || A )' % HC); gn = w.s([gd], 'simprd', '( %s -> ( A gcd N ) || N )' % HC)
gm = w.s([gz, n, m, gn, dv], 'dvdstrd', '( %s -> ( A gcd N ) || M )' % HC)
gg = w.s([w.s([gz, a, m], '3jca', '( %s -> ( ( A gcd N ) e. ZZ /\\ A e. ZZ /\\ M e. ZZ ) )' % HC), w.s([ga, gm], 'jca', '( %s -> ( ( A gcd N ) || A /\\ ( A gcd N ) || M ) )' % HC), w.inst('dvdsgcd')], 'sylc', '( %s -> ( A gcd N ) || ( A gcd M ) )' % HC)
g1 = w.s([gg, c], 'breqtrd', '( %s -> ( A gcd N ) || 1 )' % HC)
d1 = w.s([g0, w.inst('dvds1')], 'syl', '( %s -> ( ( A gcd N ) || 1 <-> ( A gcd N ) = 1 ) )' % HC)
w.qed([g1, d1], 'mpbid', '( %s -> ( A gcd N ) = 1 )' % HC); run(w)

# ---- dchrind1: the trivial character induces the trivial character
w = W('dchrind1', 'The induced character of the trivial character is the trivial character (Mathlib changeLevel_one).')
n = w.s([], 'simp1', '( %s -> N e. NN )' % H3); m = w.s([], 'simp2', '( %s -> M e. NN )' % H3); nm = w.s([], 'simp3', '( %s -> N || M )' % H3)
def one_cl(w, ante, nn, lev):
    g = w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (lev, lev))
    ab = w.s([nn, w.s([g], 'dchrabl', '( %s e. NN -> ( DChr ` %s ) e. Abel )' % (lev, lev))], 'syl', '( %s -> ( DChr ` %s ) e. Abel )' % (ante, lev))
    gr = w.s([ab], 'ablgrpd', '( %s -> ( DChr ` %s ) e. Grp )' % (ante, lev))
    return w.s([gr, w.s([w.s([], 'eqid', '%s = %s' % (DB(lev), DB(lev))), w.s([], 'eqid', '%s = %s' % (ONE(lev), ONE(lev)))], 'grpidcl', '( ( DChr ` %s ) e. Grp -> %s e. %s )' % (lev, ONE(lev), DB(lev)))], 'syl', '( %s -> %s e. %s )' % (ante, ONE(lev), DB(lev)))
on = one_cl(w, H3, n, 'N'); om = one_cl(w, H3, m, 'M')
hx = w.s([w.s([], 'id', '( %s -> %s )' % (H3, H3)), on], 'jca', '( %s -> ( %s /\\ %s e. %s ) )' % (H3, H3, ONE('N'), DB('N')))
A2 = '( %s /\\ a e. ZZ )' % H3; A3 = '( %s /\\ %s )' % (A2, COP('a', 'M'))
def one_val(w, ante, nn, lev, a, cop):
    """( ante -> ( 1lev ` ( Llev ` a ) ) = 1 ) from cop: ( ante -> ( a gcd lev ) = 1 )"""
    g = w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (lev, lev)); z = w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (lev, lev))
    o = w.s([], 'eqid', '%s = %s' % (ONE(lev), ONE(lev))); u = w.s([], 'eqid', '%s = %s' % (UZ(lev), UZ(lev))); l = w.s([], 'eqid', '%s = %s' % (LZ(lev), LZ(lev)))
    n0 = w.s([nn], 'nnnn0d', '( %s -> %s e. NN0 )' % (ante, lev))
    az = w.s([], 'simplr', '( %s -> a e. ZZ )' % ante)
    un = w.s([n0, az, w.s([z, u, l], 'znunit', '( ( %s e. NN0 /\\ a e. ZZ ) -> ( ( %s ` a ) e. %s <-> %s ) )' % (lev, LZ(lev), UZ(lev), COP('a', lev)))], 'syl2anc', '( %s -> ( ( %s ` a ) e. %s <-> %s ) )' % (ante, LZ(lev), UZ(lev), COP('a', lev)))
    lu = w.s([cop, un], 'mpbird', '( %s -> ( %s ` a ) e. %s )' % (ante, LZ(lev), UZ(lev)))
    return w.s([g, z, o, u, nn, lu], 'dchr1', '( %s -> %s = 1 )' % (ante, EV(ONE(lev), lev, 'a')))
m3 = w.s([m], 'ad2antrr', '( %s -> M e. NN )' % A3); n3 = w.s([n], 'ad2antrr', '( %s -> N e. NN )' % A3)
cm = w.s([], 'simpr', '( %s -> %s )' % (A3, COP('a', 'M')))
az3 = w.s([], 'simplr', '( %s -> a e. ZZ )' % A3)
tz = w.s([az3, w.s([n3], 'nnzd', '( %s -> N e. ZZ )' % A3), w.s([m3], 'nnzd', '( %s -> M e. ZZ )' % A3)], '3jca', '( %s -> ( a e. ZZ /\\ N e. ZZ /\\ M e. ZZ ) )' % A3)
cn = w.s([tz, w.s([nm], 'ad2antrr', '( %s -> N || M )' % A3), cm, w.inst('coprmdvdsr')], 'syl3anc', '( %s -> %s )' % (A3, COP('a', 'N')))
vm = one_val(w, A3, m3, 'M', 'a', cm); vn = one_val(w, A3, n3, 'N', 'a', cn)
e = w.s([vm, vn], 'eqtr4d', '( %s -> %s = %s )' % (A3, EV(ONE('M'), 'M', 'a'), EV(ONE('N'), 'N', 'a')))
e2 = w.s([e], 'ex', '( %s -> ( %s -> %s = %s ) )' % (A2, COP('a', 'M'), EV(ONE('M'), 'M', 'a'), EV(ONE('N'), 'N', 'a')))
e3 = w.s([e2], 'ralrimiva', '( %s -> A. a e. ZZ ( %s -> %s = %s ) )' % (H3, COP('a', 'M'), EV(ONE('M'), 'M', 'a'), EV(ONE('N'), 'N', 'a')))
r = w.s([hx, om, e3, w.inst('dchrindeq')], 'syl3anc', '( %s -> %s = %s )' % (H3, ONE('M'), IND('N', 'M', ONE('N'))))
w.qed([r], 'eqcomd', '( %s -> %s = %s )' % (H3, IND('N', 'M', ONE('N')), ONE('M'))); run(w)

# ---- dchrmulval: the product of two characters is the pointwise product
HM = '( ( N e. NN /\\ X e. %s /\\ Y e. %s ) /\\ A e. %s )' % (DB('N'), DB('N'), BZ('N'))
MULV = '( X %s Y )' % MUL('N')
w = W('dchrmulval', 'The value of the product of two Dirichlet characters (the group operation of DChr) is the product of the values.')
g, z, d, l = dchr_hyps(w, 'N'); t = w.s([], 'eqid', '%s = %s' % (MUL('N'), MUL('N'))); b = w.s([], 'eqid', '%s = %s' % (BZ('N'), BZ('N')))
x = w.s([], 'simpl2', '( %s -> X e. %s )' % (HM, DB('N'))); y = w.s([], 'simpl3', '( %s -> Y e. %s )' % (HM, DB('N'))); a = w.s([], 'simpr', '( %s -> A e. %s )' % (HM, BZ('N')))
mu = w.s([g, z, d, t, x, y], 'dchrmul', '( %s -> %s = ( X oF x. Y ) )' % (HM, MULV))
f1 = w.s([mu], 'fveq1d', '( %s -> ( %s ` A ) = ( ( X oF x. Y ) ` A ) )' % (HM, MULV))
xf = w.s([g, z, d, b, x], 'dchrf', '( %s -> X : %s --> CC )' % (HM, BZ('N'))); yf = w.s([g, z, d, b, y], 'dchrf', '( %s -> Y : %s --> CC )' % (HM, BZ('N')))
xfn = w.s([xf], 'ffnd', '( %s -> X Fn %s )' % (HM, BZ('N'))); yfn = w.s([yf], 'ffnd', '( %s -> Y Fn %s )' % (HM, BZ('N')))
bv = w.s([w.s([], 'fvex', '%s e. _V' % BZ('N'))], 'a1i', '( %s -> %s e. _V )' % (HM, BZ('N')))
of = w.s([w.s([xfn, yfn], 'jca', '( %s -> ( X Fn %s /\\ Y Fn %s ) )' % (HM, BZ('N'), BZ('N'))), w.s([bv, a], 'jca', '( %s -> ( %s e. _V /\\ A e. %s ) )' % (HM, BZ('N'), BZ('N'))), w.inst('fnfvof')], 'syl2anc', '( %s -> ( ( X oF x. Y ) ` A ) = ( ( X ` A ) x. ( Y ` A ) ) )' % HM)
w.qed([f1, of], 'eqtrd', '( %s -> ( %s ` A ) = ( ( X ` A ) x. ( Y ` A ) ) )' % (HM, MULV)); run(w)

# ---- dchrindmul: the induced character of a product
HMU = '( %s /\\ X e. %s /\\ Z e. %s )' % (H3, DB('N'), DB('N'))
YZ = IND('N', 'M', 'Z'); XZ = '( X %s Z )' % MUL('N'); YYZ = '( %s %s %s )' % (Y, MUL('M'), YZ)
w = W('dchrindmul', 'The induced character of a product is the product of the induced characters (Mathlib changeLevel is a monoid homomorphism, map_mul).')
h3 = w.s([], 'simp1', '( %s -> %s )' % (HMU, H3)); n = w.s([h3], 'simp1d', '( %s -> N e. NN )' % HMU); m = w.s([h3], 'simp2d', '( %s -> M e. NN )' % HMU)
x = w.s([], 'simp2', '( %s -> X e. %s )' % (HMU, DB('N'))); zc = w.s([], 'simp3', '( %s -> Z e. %s )' % (HMU, DB('N')))
gn, zn, dn, ln = dchr_hyps(w, 'N'); gm, zm, dm, lm = dchr_hyps(w, 'M'); tn = w.s([], 'eqid', '%s = %s' % (MUL('N'), MUL('N'))); tm = w.s([], 'eqid', '%s = %s' % (MUL('M'), MUL('M')))
xz = w.s([gn, zn, dn, tn, x, zc], 'dchrmulcl', '( %s -> %s e. %s )' % (HMU, XZ, DB('N')))
hx = w.s([h3, xz], 'jca', '( %s -> ( %s /\\ %s e. %s ) )' % (HMU, H3, XZ, DB('N')))
yd = w.s([w.s([h3, x], 'jca', '( %s -> ( %s /\\ X e. %s ) )' % (HMU, H3, DB('N'))), w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HMU, Y, DB('M')))
yzd = w.s([w.s([h3, zc], 'jca', '( %s -> ( %s /\\ Z e. %s ) )' % (HMU, H3, DB('N'))), w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HMU, YZ, DB('M')))
yyz = w.s([gm, zm, dm, tm, yd, yzd], 'dchrmulcl', '( %s -> %s e. %s )' % (HMU, YYZ, DB('M')))
A2 = '( %s /\\ a e. ZZ )' % HMU; A3 = '( %s /\\ %s )' % (A2, COP('a', 'M'))
h33 = w.s([h3], 'ad2antrr', '( %s -> %s )' % (A3, H3)); x3 = w.s([x], 'ad2antrr', '( %s -> X e. %s )' % (A3, DB('N'))); z3 = w.s([zc], 'ad2antrr', '( %s -> Z e. %s )' % (A3, DB('N')))
n3 = w.s([n], 'ad2antrr', '( %s -> N e. NN )' % A3); m3 = w.s([m], 'ad2antrr', '( %s -> M e. NN )' % A3)
a3 = w.s([], 'simplr', '( %s -> a e. ZZ )' % A3); c3 = w.s([], 'simpr', '( %s -> %s )' % (A3, COP('a', 'M')))
yd3 = w.s([yd], 'ad2antrr', '( %s -> %s e. %s )' % (A3, Y, DB('M'))); yzd3 = w.s([yzd], 'ad2antrr', '( %s -> %s e. %s )' % (A3, YZ, DB('M')))
LMA = '( %s ` a )' % LZ('M'); LNA = '( %s ` a )' % LZ('N')
m30 = w.s([m3], 'nnnn0d', '( %s -> M e. NN0 )' % A3); n30 = w.s([n3], 'nnnn0d', '( %s -> N e. NN0 )' % A3)
bm = w.s([], 'eqid', '%s = %s' % (BZ('M'), BZ('M'))); bn = w.s([], 'eqid', '%s = %s' % (BZ('N'), BZ('N')))
lab = w.s([w.s([m30, w.s([zm, bm, lm], 'znzrhfo', '( M e. NN0 -> %s : ZZ -onto-> %s )' % (LZ('M'), BZ('M')))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (A3, LZ('M'), BZ('M'))), w.inst('fof')], 'syl', '( %s -> %s : ZZ --> %s )' % (A3, LZ('M'), BZ('M')))
lab2 = w.s([lab, a3], 'ffvelcdmd', '( %s -> %s e. %s )' % (A3, LMA, BZ('M')))
lan = w.s([w.s([n30, w.s([zn, bn, ln], 'znzrhfo', '( N e. NN0 -> %s : ZZ -onto-> %s )' % (LZ('N'), BZ('N')))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (A3, LZ('N'), BZ('N'))), w.inst('fof')], 'syl', '( %s -> %s : ZZ --> %s )' % (A3, LZ('N'), BZ('N')))
lan2 = w.s([lan, a3], 'ffvelcdmd', '( %s -> %s e. %s )' % (A3, LNA, BZ('N')))
v1 = w.s([m3, yd3, yzd3, lab2, w.inst('dchrmulval')], 'syl31anc', '( %s -> ( %s ` %s ) = ( ( %s ` %s ) x. ( %s ` %s ) ) )' % (A3, YYZ, LMA, Y, LMA, YZ, LMA))
hx3 = w.s([h33, x3], 'jca', '( %s -> ( %s /\\ X e. %s ) )' % (A3, H3, DB('N'))); hz3 = w.s([h33, z3], 'jca', '( %s -> ( %s /\\ Z e. %s ) )' % (A3, H3, DB('N')))
v2 = w.s([hx3, a3, c3, w.inst('dchrindval1')], 'syl3anc', '( %s -> ( %s ` %s ) = %s )' % (A3, Y, LMA, EV('X', 'N', 'a')))
v3 = w.s([hz3, a3, c3, w.inst('dchrindval1')], 'syl3anc', '( %s -> ( %s ` %s ) = %s )' % (A3, YZ, LMA, EV('Z', 'N', 'a')))
v4 = w.s([v2, v3], 'oveq12d', '( %s -> ( ( %s ` %s ) x. ( %s ` %s ) ) = ( %s x. %s ) )' % (A3, Y, LMA, YZ, LMA, EV('X', 'N', 'a'), EV('Z', 'N', 'a')))
v5 = w.s([n3, x3, z3, lan2, w.inst('dchrmulval')], 'syl31anc', '( %s -> ( %s ` %s ) = ( %s x. %s ) )' % (A3, XZ, LNA, EV('X', 'N', 'a'), EV('Z', 'N', 'a')))
v6 = w.s([v1, v4, v5], '3eqtr4d', '( %s -> ( %s ` %s ) = ( %s ` %s ) )' % (A3, YYZ, LMA, XZ, LNA))
v7 = w.s([v6], 'ex', '( %s -> ( %s -> ( %s ` %s ) = ( %s ` %s ) ) )' % (A2, COP('a', 'M'), YYZ, LMA, XZ, LNA))
v8 = w.s([v7], 'ralrimiva', '( %s -> A. a e. ZZ ( %s -> ( %s ` %s ) = ( %s ` %s ) ) )' % (HMU, COP('a', 'M'), YYZ, LMA, XZ, LNA))
r = w.s([hx, yyz, v8, w.inst('dchrindeq')], 'syl3anc', '( %s -> %s = %s )' % (HMU, YYZ, IND('N', 'M', XZ)))
w.qed([r], 'eqcomd', '( %s -> %s = %s )' % (HMU, IND('N', 'M', XZ), YYZ)); run(w)

# ---- dchrindf: the inducing map is a function DN --> DM
w = W('dchrindf', 'The inducing map is a function from the characters mod N to the characters mod M.')
n = w.s([], 'simp1', '( %s -> N e. NN )' % H3); m = w.s([], 'simp2', '( %s -> M e. NN )' % H3)
fv = w.s([n, m, w.inst('dchrindfval')], 'syl2anc', '( %s -> %s = %s )' % (H3, INDOP('N', 'M'), INDMPT('N', 'M')))
A2 = '( %s /\\ x e. %s )' % (H3, DB('N'))
cl = w.s([w.s([], 'id', '( %s -> %s )' % (A2, A2)), w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (A2, IND('N', 'M', 'x'), DB('M')))
vv = w.s([w.s([n], 'adantr', '( %s -> N e. NN )' % A2), w.s([m], 'adantr', '( %s -> M e. NN )' % A2), w.s([], 'simpr', '( %s -> x e. %s )' % (A2, DB('N'))), w.inst('dchrindval')], 'syl3anc', '( %s -> %s = %s )' % (A2, IND('N', 'M', 'x'), INDBODY('N', 'M', 'x')))
cl2 = w.s([vv, cl], 'eqeltrrd', '( %s -> %s e. %s )' % (A2, INDBODY('N', 'M', 'x'), DB('M')))
fm = w.s([cl2, w.s([], 'eqid', '%s = %s' % (INDMPT('N', 'M'), INDMPT('N', 'M')))], 'fmptd', '( %s -> %s : %s --> %s )' % (H3, INDMPT('N', 'M'), DB('N'), DB('M')))
fe = w.s([fv], 'feq1d', '( %s -> ( %s : %s --> %s <-> %s : %s --> %s ) )' % (H3, INDOP('N', 'M'), DB('N'), DB('M'), INDMPT('N', 'M'), DB('N'), DB('M')))
w.qed([fm, fe], 'mpbird', '( %s -> %s : %s --> %s )' % (H3, INDOP('N', 'M'), DB('N'), DB('M'))); run(w)

# ---- dchrindghm: the inducing map is a group homomorphism
GHM = '( ( DChr ` N ) GrpHom ( DChr ` M ) )'
w = W('dchrindghm', 'The inducing map is a group homomorphism of the character groups (Mathlib changeLevel : DirichletCharacter R n ->* DirichletCharacter R m).')
n = w.s([], 'simp1', '( %s -> N e. NN )' % H3); m = w.s([], 'simp2', '( %s -> M e. NN )' % H3)
dn = w.s([], 'eqid', '%s = %s' % (DB('N'), DB('N'))); dm = w.s([], 'eqid', '%s = %s' % (DB('M'), DB('M')))
tn = w.s([], 'eqid', '%s = %s' % (MUL('N'), MUL('N'))); tm = w.s([], 'eqid', '%s = %s' % (MUL('M'), MUL('M')))
gn = w.s([n, w.s([w.s([], 'eqid', '( DChr ` N ) = ( DChr ` N )')], 'dchrabl', '( N e. NN -> ( DChr ` N ) e. Abel )')], 'syl', '( %s -> ( DChr ` N ) e. Abel )' % H3)
gm = w.s([m, w.s([w.s([], 'eqid', '( DChr ` M ) = ( DChr ` M )')], 'dchrabl', '( M e. NN -> ( DChr ` M ) e. Abel )')], 'syl', '( %s -> ( DChr ` M ) e. Abel )' % H3)
grn = w.s([gn], 'ablgrpd', '( %s -> ( DChr ` N ) e. Grp )' % H3); grm = w.s([gm], 'ablgrpd', '( %s -> ( DChr ` M ) e. Grp )' % H3)
f = w.s([], 'dchrindf', '( %s -> %s : %s --> %s )' % (H3, INDOP('N', 'M'), DB('N'), DB('M')))
A2 = '( %s /\\ ( x e. %s /\\ y e. %s ) )' % (H3, DB('N'), DB('N'))
lin = w.s([w.s([], 'simpl', '( %s -> %s )' % (A2, H3)), w.s([], 'simprl', '( %s -> x e. %s )' % (A2, DB('N'))), w.s([], 'simprr', '( %s -> y e. %s )' % (A2, DB('N'))), w.inst('dchrindmul')], 'syl3anc',
          '( %s -> %s = ( %s %s %s ) )' % (A2, IND('N', 'M', '( x %s y )' % MUL('N')), IND('N', 'M', 'x'), MUL('M'), IND('N', 'M', 'y')))
w.qed([dn, dm, tn, tm, grn, grm, f, lin], 'isghmd', '( %s -> %s e. %s )' % (H3, INDOP('N', 'M'), GHM)); run(w)

# ---- dchrindinv: the induced character of the inverse (conjugate) character
w = W('dchrindinv', 'The induced character of the inverse (= conjugate, dchrinv) character is the inverse of the induced character (Mathlib map_inv for changeLevel).')
h3 = w.s([], 'simpl', '( %s -> %s )' % (HX, H3)); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HX, DB('N')))
gh = w.s([h3, w.inst('dchrindghm')], 'syl', '( %s -> %s e. %s )' % (HX, INDOP('N', 'M'), GHM))
dn = w.s([], 'eqid', '%s = %s' % (DB('N'), DB('N'))); i1 = w.s([], 'eqid', '%s = %s' % (INV('N'), INV('N'))); i2 = w.s([], 'eqid', '%s = %s' % (INV('M'), INV('M')))
w.qed([gh, x, w.s([dn, i1, i2], 'ghminv', '( ( %s e. %s /\\ X e. %s ) -> %s = ( %s ` %s ) )' % (INDOP('N', 'M'), GHM, DB('N'), IND('N', 'M', '( %s ` X )' % INV('N')), INV('M'), Y))], 'syl2anc',
      '( %s -> %s = ( %s ` %s ) )' % (HX, IND('N', 'M', '( %s ` X )' % INV('N')), INV('M'), Y)); run(w)

# ---- dchrindtr: inducing in two steps
HT = '( ( N e. NN /\\ M e. NN /\\ K e. NN ) /\\ ( N || M /\\ M || K ) /\\ X e. %s )' % DB('N')
YK = IND('M', 'K', Y)
w = W('dchrindtr', 'Inducing from N to M and then to K is inducing from N to K (Mathlib changeLevel_trans).')
n = w.s([], 'simp11', '( %s -> N e. NN )' % HT); m = w.s([], 'simp12', '( %s -> M e. NN )' % HT); kk = w.s([], 'simp13', '( %s -> K e. NN )' % HT)
nm = w.s([], 'simp2l', '( %s -> N || M )' % HT); mk = w.s([], 'simp2r', '( %s -> M || K )' % HT); x = w.s([], 'simp3', '( %s -> X e. %s )' % (HT, DB('N')))
nz = w.s([n], 'nnzd', '( %s -> N e. ZZ )' % HT); mz = w.s([m], 'nnzd', '( %s -> M e. ZZ )' % HT); kz = w.s([kk], 'nnzd', '( %s -> K e. ZZ )' % HT)
nk = w.s([nz, mz, kz, nm, mk], 'dvdstrd', '( %s -> N || K )' % HT)
hnm = w.s([n, m, nm], '3jca', '( %s -> %s )' % (HT, H3)); hmk = w.s([m, kk, mk], '3jca', '( %s -> ( M e. NN /\\ K e. NN /\\ M || K ) )' % HT); hnk = w.s([n, kk, nk], '3jca', '( %s -> ( N e. NN /\\ K e. NN /\\ N || K ) )' % HT)
hx = w.s([hnm, x], 'jca', '( %s -> ( %s /\\ X e. %s ) )' % (HT, H3, DB('N')))
yd = w.s([hx, w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HT, Y, DB('M')))
hy = w.s([hmk, yd], 'jca', '( %s -> ( ( M e. NN /\\ K e. NN /\\ M || K ) /\\ %s e. %s ) )' % (HT, Y, DB('M')))
ykd = w.s([hy, w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HT, YK, DB('K')))
hxk = w.s([hnk, x], 'jca', '( %s -> ( ( N e. NN /\\ K e. NN /\\ N || K ) /\\ X e. %s ) )' % (HT, DB('N')))
A2 = '( %s /\\ a e. ZZ )' % HT; A3 = '( %s /\\ %s )' % (A2, COP('a', 'K'))
a3 = w.s([], 'simplr', '( %s -> a e. ZZ )' % A3); ck = w.s([], 'simpr', '( %s -> %s )' % (A3, COP('a', 'K')))
tz = w.s([a3, w.s([mz], 'ad2antrr', '( %s -> M e. ZZ )' % A3), w.s([kz], 'ad2antrr', '( %s -> K e. ZZ )' % A3)], '3jca', '( %s -> ( a e. ZZ /\\ M e. ZZ /\\ K e. ZZ ) )' % A3)
cm = w.s([tz, w.s([mk], 'ad2antrr', '( %s -> M || K )' % A3), ck, w.inst('coprmdvdsr')], 'syl3anc', '( %s -> %s )' % (A3, COP('a', 'M')))
v1 = w.s([w.s([hy], 'ad2antrr', '( %s -> ( ( M e. NN /\\ K e. NN /\\ M || K ) /\\ %s e. %s ) )' % (A3, Y, DB('M'))), a3, ck, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (A3, EV(YK, 'K', 'a'), EV(Y, 'M', 'a')))
v2 = w.s([w.s([hx], 'ad2antrr', '( %s -> ( %s /\\ X e. %s ) )' % (A3, H3, DB('N'))), a3, cm, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (A3, EV(Y, 'M', 'a'), EV('X', 'N', 'a')))
v3 = w.s([v1, v2], 'eqtrd', '( %s -> %s = %s )' % (A3, EV(YK, 'K', 'a'), EV('X', 'N', 'a')))
v4 = w.s([v3], 'ex', '( %s -> ( %s -> %s = %s ) )' % (A2, COP('a', 'K'), EV(YK, 'K', 'a'), EV('X', 'N', 'a')))
v5 = w.s([v4], 'ralrimiva', '( %s -> A. a e. ZZ ( %s -> %s = %s ) )' % (HT, COP('a', 'K'), EV(YK, 'K', 'a'), EV('X', 'N', 'a')))
w.qed([hxk, ykd, v5, w.inst('dchrindeq')], 'syl3anc', '( %s -> %s = %s )' % (HT, YK, IND('N', 'K', 'X'))); run(w)
